using UnityEngine;
public class WoodlandRagdoll:MonoBehaviour {
 public Animator animator;public WoodlandCompanion companion;public Rigidbody[] bodies;public Collider[] hitColliders;public bool collapsed;Vector3[] restPositions;Quaternion[] restRotations;
 public void Initialise(){if(bodies==null)return;foreach(var rb in bodies){rb.isKinematic=true;rb.useGravity=false;rb.interpolation=RigidbodyInterpolation.None;rb.collisionDetectionMode=CollisionDetectionMode.ContinuousSpeculative;}if(hitColliders!=null)for(int i=0;i<hitColliders.Length;i++){hitColliders[i].isTrigger=true;for(int j=i+1;j<hitColliders.Length;j++)Physics.IgnoreCollision(hitColliders[i],hitColliders[j],true);}}
 void Awake(){restPositions=new Vector3[bodies.Length];restRotations=new Quaternion[bodies.Length];for(int i=0;i<bodies.Length;i++){restPositions[i]=bodies[i].transform.localPosition;restRotations[i]=bodies[i].transform.localRotation;}var controller=GetComponentInParent<CharacterController>();if(controller)foreach(var col in hitColliders)Physics.IgnoreCollision(col,controller,true);Initialise();}
 public void ResetBody(){collapsed=false;Initialise();if(restPositions!=null)for(int i=0;i<bodies.Length;i++){bodies[i].transform.localPosition=restPositions[i];bodies[i].transform.localRotation=restRotations[i];}if(animator)animator.enabled=true;gameObject.SetActive(false);}
 public void Collapse(BodyRegion region,Vector3 point,Vector3 impulse){if(collapsed)return;if(!gameObject.activeSelf)gameObject.SetActive(true);collapsed=true;if(companion)companion.enabled=false;if(animator)animator.enabled=false;if(bodies==null)return;foreach(var c in hitColliders)c.isTrigger=false;foreach(var rb in bodies){rb.isKinematic=false;rb.interpolation=RigidbodyInterpolation.Interpolate;rb.useGravity=true;rb.WakeUp();}Rigidbody target=null;float distance=float.MaxValue;foreach(var rb in bodies){float d=(rb.worldCenterOfMass-point).sqrMagnitude;if(d<distance){target=rb;distance=d;}}if(target)target.AddForceAtPosition(impulse,point,ForceMode.Impulse);}
}
